import React, { useState, useMemo, useEffect, ReactNode } from "react";
import { Button, Modal, Typography, Tree, Space, Form, Message, Popconfirm } from "@arco-design/web-react";
import { IconDelete, IconDown, IconDriveFile, IconEdit, IconPlus } from "@arco-design/web-react/icon";
import Store from './store';
import { useObserver } from 'mobx-react-lite';
import { toJS } from 'mobx';
import { JSONSchemaCustom, SchemaForm } from "@/components/schema";
import ajax from "@/utils/ajax";
import styles from './style.module.less';
import { convertToTree } from "@/utils";
import { Pattern } from "@/types/pattern";
import pStore from '../../store';
import { TextInput } from "@/components/custom";



interface FileListProps {
    // 切换文件时更新
    onChangeFile?: (item: any) => void;
}

const FileList = (props: FileListProps) => {

    const [store] = useState(() => new Store());
    
    useEffect(() => {
        store.setPaths(pStore.files);
    },[pStore.files])
    const schema = useMemo(() => {
        return {
            "type": "object",
            "properties": {
                "title": {
                    "type": "string",
                    "title": "文件地址",
                    "pattern": Pattern.path,
                },
                "sort": {
                    "type": "number",
                    "title": "排序"
                }
            },
            "required": ["title", "sort"]
        } as JSONSchemaCustom
    },[])

    return useObserver(() => {

        const list = useMemo(() => {
            return convertToTree(toJS(store.contents).map((o) => {
                return {
                    ...o,
                    id: o.item? o.item.id : o.id,
                    // icons: {
                    //     switcherIcon: o.item? <IconDriveFile /> : <IconDown />,
                    // },
                };
            })
            // .sort((a,b) => {
            //     return a.fileName.localeCompare(b.fileName);
            // })
            , 'path', 'parentPath')
        },[store.contents])
        const [form] = Form.useForm();

        // console.log('store.initValues', store.initValues)
        return (
            <div className={styles.file}>
                <div style={{ display:"flex", alignItems: "center", justifyContent: "space-between" }}>
                    <Typography.Title style={{ margin: 0 }} heading={6}>Pages</Typography.Title>
                    <Button shape="round" type="text" size="mini"
                        onClick={() => {
                            // ajax.post('/apijson/post', {
                            //     "Page": {
                            //         title: store.getPathName(),
                            //     }
                            // }).then((res) => {
                            //     pStore.getPaths();
                            // })
                            form.clearFields();
                            store.setInitValues({});
                        }}
                    >
                        <IconPlus />
                    </Button>
                </div>
                <Tree
                    className={styles.tree}
                    key={list.length}
                    icons={{
                        // switcherIcon: <IconDown />,
                        // dragIcon: <IconDragArrow />,
                    }}
                    treeData={list}
                    fieldNames={{
                        key: "id",
                        title: 'fileName',
                        children: "children"
                    }}
                    blockNode
                    selectedKeys={[store.pageId]}
                    expandedKeys={store.expandKeys}
                    onExpand={store.setExpands}
                    onSelect={(a,{ selectedNodes }) => {
                        const { dataRef } = selectedNodes[0].props;
                        console.log('dataRef', dataRef);
                        if(dataRef.item){
                            // 打开文件
                            pStore.setSelectId(dataRef.item.id);
                            pStore.setFileVisible(false);
                        }else {
                            // 打开目录
                            store.saveExpandStatus(dataRef.id);
                        }
                    }}
                    renderTitle={({ title, dataRef, ...props }) => {
                        // return (
                        //     <TextInput
                        //         key={dataRef.id}
                        //         defaultValue={title as string}
                        //         pattern={Pattern.path}
                        //         onPressEnter={(e) => {
                        //             const value = e.target.value;
                        //             console.log('e', e);
                        //             return;
                        //             ajax.post('/apijson/put', {
                        //                 Page: {
                        //                     id: dataRef.id,
                        //                     title: "pages/size"
                        //                 }
                        //             })
                        //         }}
                        //     />
                        // )
                        return (
                            <div key={dataRef.id}>{title}</div>
                        );
                    }}
                    renderExtra={(node) => {
                        const data = node.dataRef;
                        if(!data.item) return;
                        const item = data.item;

                        return (
                            <Space 
                                style={{
                                    position: 'absolute',
                                    right: 8,
                                    fontSize: 12,
                                    top: 10,
                                    color: '#3370ff',
                                }}
                            >
                                <IconPlus 
                                    onClick={() => {
                                        form.clearFields();
                                        store.setInitValues({ title: `${item.title}/` });
                                    }}
                                />
                                <IconEdit 
                                    onClick={() => {
                                        form.clearFields();
                                        store.setInitValues(item)
                                    }}
                                />
                                <Popconfirm
                                    focusLock
                                    title={`请确认删除 [${item.title}] 文件`}
                                    onOk={() => {
                                        pStore.deletePaths(item);
                                    }}

                                >
                                    <IconDelete />
                                </Popconfirm>
                            </Space>
                        );
                    }}
                    showLine
                >
                </Tree>
                <Modal 
                    visible={Boolean(store.initValues)}
                    title={store.title}
                    onCancel={() => {
                        store.setInitValues("");
                    }}
                    onOk={() => {
                        const params = form.getFieldsValue();
                        if(store.initValues.id){
                            if(store.pageList.find((o) => o.title == params.title && o.title != store.initValues.title)){
                                Message.error("当前文件已存在")
                                return
                            }
                            ajax.post('/apijson/put', {
                                Page: {
                                    id: store.initValues.id,
                                    ...params,
                                }
                            }).then(() => {
                                store.setInitValues("");
                                pStore.getPaths();
                            })
                        }else {
                            if(store.pageList.find((o) => o.title == params.title)){
                                Message.error("当前文件已存在")
                                return
                            }
                            ajax.post('/apijson/post', {
                                Page: {
                                    ...params
                                }
                            }).then(() => {
                                store.setInitValues("");
                                pStore.getPaths();
                            })
                        }
                    }}
                    unmountOnExit
                >
                    <SchemaForm
                        form={form}
                        generagteProps={{ cols: 24 }}
                        schema={schema}
                        initialValues={toJS(store.initValues)}                    
                    ></SchemaForm>
                </Modal>
            </div>
        )
    })
}

export default FileList;