import React from "react";
import { observable, action, computed, toJS, makeObservable } from 'mobx';
import ajax from "@/utils/ajax";
import { getUuid } from "@/utils";
import pStore from '../../store';
import { processPageList } from "@/utils/path";
import { ApiPageData } from "@/types/page";

interface PageProps {
    id: string;
    title: string;
}

interface ContentItem {
    id: string;
    item?: PageProps;
    // 当前路径名称
    path: string;
    // 上级路径名称
    parentPath: string;
    // 文件名称（如果是文件的话）
    fileName?: string;
    // children?: ContentItem[];
}

class Store {
    constructor() {
        makeObservable(this);
    }

    @computed get pageId(){
        return pStore.selectId;
    }

    @observable initValues: ApiPageData;
    @action setInitValues = (obj) => {
        this.initValues = obj;
    }

    @computed get title(){
        if(this.initValues){
            return `${this.initValues.id? "编辑" : "新增"}文件`;
        }
        return "新增文件";
    }

    /**
     * 创建目录
     */
    @observable contents: ContentItem[] = [];

    nodePath = {};
    @observable pageList: ApiPageData[] = [];
    @action
    setPaths = (list) => {
        this.pageList = list;
        this.contents = [];
        for (const item of list) {
            this.nodePath[item.title] = true;
        }
        this.contents = processPageList(list, "title");
        this.setExpands(this.contents.filter((o) => o.id));
    }
    getPathName = () => {
        let i = 1;
        let name = `page-${i}`;
        while(this.nodePath[name]){ 
            name = `page-${++i}`;
        }
        return name;
    }

    // 添加目录名称映射
    contentAlias = {};



    @observable expands = [];

    @computed get expandKeys(){
        return toJS(this.expands);
    }

    @action
    setExpands = (list) => {
        this.expands = list;
    }

    @action
    addExpand = (key: string) => {
        if(!this.expands.includes(key)){
            this.expands = [...this.expands, key];
        }
    }

    @action
    delExpand = (key: string) => {
        if(this.expands.includes(key)){
            this.expands = this.expands.filter((o) => o !== key)
        }
    }

    @action
    saveExpandStatus = (key: string) => {
        if(this.expands.includes(key)){
            this.setExpands(this.expands.filter((o) => o !== key))
        }else {
            this.setExpands([...this.expands, key])
        }
    }
}

export default Store;