import ajax from '@/utils/ajax';
import { observable, action, makeObservable } from 'mobx';
import { Message } from '@arco-design/web-react';
import { Store as PageStore } from "@/components/CustomPage";
import { moduleStore } from 'react-converter-code';
import module from "@/store/module";
import pageStore from "@/store/page";

type drawerType = "file" | "module" | "";
class Store {
    @observable fileVisible: boolean = false;
    @action
    setFileVisible = (bool) => {
        this.fileVisible = bool;
    }

    @observable drawerType: drawerType = "file";
    @action setDrawerType = (type: drawerType) => {
        this.drawerType = type;
    }

    @observable pages = {};

    @observable tabs = [];
    @action addTabls = (key: string, title: string) => {
        this.tabs = [...this.tabs, { key, title }];
    }


    // 添加页面store
    addPageStore = async (uid: string) => {
        const data = this.files.find((o) => o.id == uid);
        if(data){
            // 文件查找成功
            this.pages[uid] = await pageStore.addTabPage(data);
            this.addTabls(uid, data.title);
        }
    }

    // 当前选择的页面
    @observable selectId = "";
    // 切换选择的页面
    @action
    setSelectId = async (id: string) => {
        if(!this.pages[id]) {
            await this.addPageStore(id);
        }
        
        this.selectId = id;
    }


    @observable files: any[] = [];
    @action
    setFiles = (data: any[]) => {
        this.files = data;
    }


    // 获取文件信息
    getPaths = () => {
        // 获取所有页面文件
        ajax.post('/apijson/get', {
            ["Page[]"]: {
                "count": 0,
                "Page": {
                    "@order": "sort+"
                }
            }
        }).then((res) => {
            this.setFiles(res.Page);
            if(!this.selectId && res.Page[0]){
                // 首次加载如果存在页面则默认选中第一个文件
                this.setSelectId(res.Page[0].id)
            }
        })
    }

    // 删除文件信息
    deletePaths = (item: any) => {
        ajax.post('/apijson/delete', {
            Page: { id: item.id }
        }).then((res) => {
            Message.success("删除成功");
            this.getPaths();
        })
    }


    /** 页面保存 */
    savePage = async (store: PageStore) => {
        const data = store.getData();
        const { components } = data;
        // console.log('data', data);
        const list = [];
        for (const key of components) {
            const element = moduleStore.elements.get(key);
            if(element && element.source === "custom" && element.isPublic){
                list.push(element);
            }
        }
        if(list.length){
            // 存在未下载的组件模块， 先将组件模块下载下来
            await module.syncModule(list, true);
            for (const item of list) {
                const element: any = moduleStore.elements.get(item.key);
                moduleStore.elements.set(item.key, {
                    ...element,
                    isPublic: false, 
                })
            }
        }
        await store.validate().then(async (data) => {
            return ajax.post('/apijson/put', {
                Page: {
                    id: store.uid,
                    content: JSON.stringify(data),
                    extraInfo: {
                        cssStr: data.cssStr,
                        components: data.components,
                    },
                    jsxRender: await store.getRenderText(),
                }
            }).then(() => {
                Message.success('页面保存成功');
                // history.goBack();
            })
        })
    }

    constructor() {
        makeObservable(this);
    }
}

export default new Store();